#![cfg(feature = "grpc")]

//! gRPC API integration tests: a server on a random port, driven by a tonic-generated client.

use std::sync::Arc;

use base64::Engine;
use traverse_core::graph::Graph;
use traverse_core::tx::MvccStore;
use traverse_server::auth::{AuthCatalog, Role};
use traverse_server::grpc::GrpcServer;
use traverse_server::registry::DatabaseRegistry;

#[allow(clippy::all)] // generated by tonic-build
mod proto {
    tonic::include_proto!("traverse.v1");
}

use proto::traverse_service_client::TraverseServiceClient;
use proto::value::Kind;

// -- Test helpers -----------------------------------------------------

async fn start_grpc_server() -> (String, tokio::sync::oneshot::Sender<()>) {
    let store = Arc::new(MvccStore::new(Graph::new()));
    let registry = Arc::new(DatabaseRegistry::single("neo4j".to_string(), store, None));
    let (shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel();
    let grpc = GrpcServer::new(registry, "127.0.0.1:0".parse().unwrap());
    let addr = grpc.run_until_shutdown(shutdown_rx).await.unwrap();
    let url = format!("http://{addr}");
    // Give the server a moment to start
    tokio::time::sleep(std::time::Duration::from_millis(50)).await;
    (url, shutdown_tx)
}

/// gRPC server with auth on, seeded with an admin plus optional extra users.
async fn start_grpc_server_with_auth(
    extra_users: &[(&str, &str, Role)],
) -> (String, tokio::sync::oneshot::Sender<()>) {
    let store = Arc::new(MvccStore::new(Graph::new()));
    let registry = Arc::new(DatabaseRegistry::single("neo4j".to_string(), store, None));

    let mut catalog = AuthCatalog::new();
    catalog.add_user("admin", "admin123", Role::Admin).unwrap();
    for &(user, pass, role) in extra_users {
        catalog.add_user(user, pass, role).unwrap();
    }
    let catalog = Arc::new(std::sync::RwLock::new(catalog));

    let (shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel();
    let grpc = GrpcServer::new(registry, "127.0.0.1:0".parse().unwrap()).with_auth_catalog(catalog);
    let addr = grpc.run_until_shutdown(shutdown_rx).await.unwrap();
    let url = format!("http://{addr}");
    tokio::time::sleep(std::time::Duration::from_millis(50)).await;
    (url, shutdown_tx)
}

/// Basic auth header value for user:pass.
fn basic_auth(user: &str, pass: &str) -> String {
    let encoded = base64::engine::general_purpose::STANDARD.encode(format!("{user}:{pass}"));
    format!("Basic {encoded}")
}

/// Tonic request with Basic auth metadata.
fn authed_request<T>(inner: T, user: &str, pass: &str) -> tonic::Request<T> {
    let mut req = tonic::Request::new(inner);
    req.metadata_mut()
        .insert("authorization", basic_auth(user, pass).parse().unwrap());
    req
}

fn string_val(s: &str) -> proto::Value {
    proto::Value {
        kind: Some(Kind::StringValue(s.to_string())),
    }
}

fn int_val(n: i64) -> proto::Value {
    proto::Value {
        kind: Some(Kind::IntValue(n)),
    }
}

// -- Tests ------------------------------------------------------------

#[tokio::test]
async fn create_node_and_get_node_roundtrip() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();

    let resp = client
        .create_node(proto::CreateNodeRequest {
            labels: vec!["Person".into()],
            properties: [("name".into(), string_val("Alice"))].into_iter().collect(),
            transaction_id: String::new(),
        })
        .await
        .unwrap()
        .into_inner();

    let node = resp.node.unwrap();
    assert_eq!(node.labels, vec!["Person"]);
    assert_eq!(
        node.properties.get("name").and_then(|v| match &v.kind {
            Some(Kind::StringValue(s)) => Some(s.as_str()),
            _ => None,
        }),
        Some("Alice")
    );

    // Get the same node back
    let get_resp = client
        .get_node(proto::GetNodeRequest {
            id: node.id,
            transaction_id: String::new(),
        })
        .await
        .unwrap()
        .into_inner();

    let got = get_resp.node.unwrap();
    assert_eq!(got.id, node.id);
    assert_eq!(got.labels, vec!["Person"]);
}

#[tokio::test]
async fn create_edge_and_get_edge_roundtrip() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();

    let n1 = client
        .create_node(proto::CreateNodeRequest {
            labels: vec!["Person".into()],
            properties: [("name".into(), string_val("Alice"))].into_iter().collect(),
            transaction_id: String::new(),
        })
        .await
        .unwrap()
        .into_inner()
        .node
        .unwrap();

    let n2 = client
        .create_node(proto::CreateNodeRequest {
            labels: vec!["Person".into()],
            properties: [("name".into(), string_val("Bob"))].into_iter().collect(),
            transaction_id: String::new(),
        })
        .await
        .unwrap()
        .into_inner()
        .node
        .unwrap();

    let edge_resp = client
        .create_edge(proto::CreateEdgeRequest {
            source: n1.id,
            target: n2.id,
            edge_type: "KNOWS".into(),
            properties: [("since".into(), int_val(2020))].into_iter().collect(),
            transaction_id: String::new(),
        })
        .await
        .unwrap()
        .into_inner();

    let edge = edge_resp.edge.unwrap();
    assert_eq!(edge.edge_type, "KNOWS");
    assert_eq!(edge.source, n1.id);
    assert_eq!(edge.target, n2.id);

    // Get edge back
    let got = client
        .get_edge(proto::GetEdgeRequest {
            id: edge.id,
            transaction_id: String::new(),
        })
        .await
        .unwrap()
        .into_inner()
        .edge
        .unwrap();

    assert_eq!(got.id, edge.id);
    assert_eq!(got.edge_type, "KNOWS");
}

#[tokio::test]
async fn delete_node() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();

    let node = client
        .create_node(proto::CreateNodeRequest {
            labels: vec!["Temp".into()],
            properties: Default::default(),
            transaction_id: String::new(),
        })
        .await
        .unwrap()
        .into_inner()
        .node
        .unwrap();

    client
        .delete_node(proto::DeleteNodeRequest {
            id: node.id,
            detach: false,
            transaction_id: String::new(),
        })
        .await
        .unwrap();

    // Get should now fail
    let err = client
        .get_node(proto::GetNodeRequest {
            id: node.id,
            transaction_id: String::new(),
        })
        .await
        .unwrap_err();

    assert_eq!(err.code(), tonic::Code::NotFound);
}

