#[tokio::test]
async fn execute_query_create_and_match() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();

    // CREATE query
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "CREATE (n:City {name: 'Stockholm'}) RETURN n.name".into(),
            parameters: Default::default(),
            transaction_id: String::new(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();

    let mut messages = vec![];
    while let Some(msg) = tokio_stream::StreamExt::next(&mut stream).await {
        messages.push(msg.unwrap());
    }

    // Should have header, row, footer
    assert!(
        messages.len() >= 3,
        "expected header+row+footer, got {}",
        messages.len()
    );

    // Verify header
    if let Some(proto::execute_query_response::Payload::Header(h)) = &messages[0].payload {
        assert_eq!(h.columns, vec!["n.name"]);
    } else {
        panic!("expected header");
    }

    // Verify row
    if let Some(proto::execute_query_response::Payload::Row(r)) = &messages[1].payload {
        assert_eq!(r.values.len(), 1);
        match &r.values[0].kind {
            Some(Kind::StringValue(s)) => assert_eq!(s, "Stockholm"),
            other => panic!("expected string, got {other:?}"),
        }
    } else {
        panic!("expected row");
    }

    // Verify footer has stats
    if let Some(proto::execute_query_response::Payload::Footer(f)) = &messages[2].payload {
        let stats = f.stats.as_ref().unwrap();
        assert_eq!(stats.nodes_created, 1);
        assert!(!f.bookmark.is_empty());
    } else {
        panic!("expected footer");
    }

    // MATCH query
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "MATCH (n:City) RETURN n.name".into(),
            parameters: Default::default(),
            transaction_id: String::new(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();

    let mut messages = vec![];
    while let Some(msg) = tokio_stream::StreamExt::next(&mut stream).await {
        messages.push(msg.unwrap());
    }

    assert!(messages.len() >= 3);
    if let Some(proto::execute_query_response::Payload::Row(r)) = &messages[1].payload {
        match &r.values[0].kind {
            Some(Kind::StringValue(s)) => assert_eq!(s, "Stockholm"),
            other => panic!("expected string, got {other:?}"),
        }
    }
}

#[tokio::test]
async fn execute_query_streaming_multiple_rows() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();

    // Create multiple nodes
    let mut create_stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "CREATE (:Num {v: 1}), (:Num {v: 2}), (:Num {v: 3})".into(),
            parameters: Default::default(),
            transaction_id: String::new(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();

    // Drain the create stream
    while tokio_stream::StreamExt::next(&mut create_stream)
        .await
        .is_some()
    {}

    // Match and stream
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "MATCH (n:Num) RETURN n.v ORDER BY n.v".into(),
            parameters: Default::default(),
            transaction_id: String::new(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();

    let mut rows = vec![];
    while let Some(msg) = tokio_stream::StreamExt::next(&mut stream).await {
        let msg = msg.unwrap();
        if let Some(proto::execute_query_response::Payload::Row(r)) = msg.payload {
            rows.push(r);
        }
    }

    assert_eq!(rows.len(), 3);
}

#[tokio::test]
async fn begin_commit_transaction() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();

    let tx_resp = client
        .begin_transaction(proto::BeginTransactionRequest::default())
        .await
        .unwrap()
        .into_inner();

    let tx_id = tx_resp.transaction_id;
    assert!(!tx_id.is_empty());

    // Execute within transaction
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "CREATE (n:TxTest {v: 42}) RETURN n.v".into(),
            parameters: Default::default(),
            transaction_id: tx_id.clone(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();

    // Drain stream
    while tokio_stream::StreamExt::next(&mut stream).await.is_some() {}

    // Commit
    let commit_resp = client
        .commit_transaction(proto::CommitTransactionRequest {
            transaction_id: tx_id,
        })
        .await
        .unwrap()
        .into_inner();

    assert!(!commit_resp.bookmark.is_empty());

    // Verify data is visible after commit
    let count = client
        .get_node_count(proto::GetNodeCountRequest {})
        .await
        .unwrap()
        .into_inner()
        .count;

    assert_eq!(count, 1);
}

#[tokio::test]
async fn begin_rollback_transaction() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();

    let tx_id = client
        .begin_transaction(proto::BeginTransactionRequest::default())
        .await
        .unwrap()
        .into_inner()
        .transaction_id;

    // Create a node in the tx
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "CREATE (:Ghost)".into(),
            parameters: Default::default(),
            transaction_id: tx_id.clone(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();

    while tokio_stream::StreamExt::next(&mut stream).await.is_some() {}

    // Rollback
    client
        .rollback_transaction(proto::RollbackTransactionRequest {
            transaction_id: tx_id,
        })
        .await
        .unwrap();

    // Node count should be 0
    let count = client
        .get_node_count(proto::GetNodeCountRequest {})
        .await
        .unwrap()
        .into_inner()
        .count;

    assert_eq!(count, 0);
}

