#[tokio::test]
async fn streaming_read_returns_correct_rows() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();

    // Create 100 nodes via batch API
    let nodes: Vec<proto::CreateNodeRequest> = (0..100)
        .map(|i| proto::CreateNodeRequest {
            labels: vec!["StreamTest".into()],
            properties: [("idx".into(), int_val(i))].into_iter().collect(),
            transaction_id: String::new(),
        })
        .collect();
    client
        .batch_create_nodes(proto::BatchCreateNodesRequest {
            nodes,
            transaction_id: String::new(),
        })
        .await
        .unwrap();

    // Read all nodes back via streaming execute_query
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "MATCH (n:StreamTest) RETURN n.idx ORDER BY n.idx".into(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();

    let mut header = None;
    let mut rows = vec![];
    let mut footer = None;
    while let Some(msg) = tokio_stream::StreamExt::next(&mut stream).await {
        let msg = msg.unwrap();
        match msg.payload {
            Some(proto::execute_query_response::Payload::Header(h)) => header = Some(h),
            Some(proto::execute_query_response::Payload::Row(r)) => rows.push(r),
            Some(proto::execute_query_response::Payload::Footer(f)) => footer = Some(f),
            None => {}
        }
    }

    // Verify header
    let h = header.expect("expected header");
    assert_eq!(h.columns, vec!["n.idx"]);

    // Verify all 100 rows received with correct values
    assert_eq!(rows.len(), 100);
    for (i, row) in rows.iter().enumerate() {
        assert_eq!(row.values.len(), 1);
        match &row.values[0].kind {
            Some(Kind::IntValue(v)) => assert_eq!(*v, i as i64),
            other => panic!("expected int at row {i}, got {other:?}"),
        }
    }

    // Verify footer
    let f = footer.expect("expected footer");
    assert_eq!(f.query_type, "r");
    assert!(!f.contains_updates);
}

