// -- Plan cache tests ------------------------------------------------

/// First column of every row, as i64.
async fn query_int_column(
    client: &mut TraverseServiceClient<tonic::transport::Channel>,
    query: &str,
) -> Vec<i64> {
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: query.into(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();

    let mut vals = vec![];
    while let Some(msg) = tokio_stream::StreamExt::next(&mut stream).await {
        let msg = msg.unwrap();
        if let Some(proto::execute_query_response::Payload::Row(r)) = msg.payload
            && let Some(Kind::IntValue(v)) = r.values.first().and_then(|v| v.kind.as_ref())
        {
            vals.push(*v);
        }
    }
    vals
}

#[tokio::test]
async fn plan_cache_returns_correct_results_on_repeated_query() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();

    // Create some data
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "CREATE (:Cached {v: 1}), (:Cached {v: 2}), (:Cached {v: 3})".into(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();
    while tokio_stream::StreamExt::next(&mut stream).await.is_some() {}

    // Run same MATCH twice - second hit should come from cache
    let query = "MATCH (n:Cached) RETURN n.v ORDER BY n.v";
    let first = query_int_column(&mut client, query).await;
    let second = query_int_column(&mut client, query).await;

    assert_eq!(first, vec![1, 2, 3]);
    assert_eq!(second, vec![1, 2, 3]);
}

#[tokio::test]
async fn plan_cache_invalidated_after_index_creation() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();

    // Create data
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "CREATE (:Idx {v: 10}), (:Idx {v: 20})".into(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();
    while tokio_stream::StreamExt::next(&mut stream).await.is_some() {}

    // First query populates cache
    let query = "MATCH (n:Idx) RETURN n.v ORDER BY n.v";
    let before = query_int_column(&mut client, query).await;
    assert_eq!(before, vec![10, 20]);

    // Create an index - should invalidate cache
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "CREATE INDEX idx_test FOR (n:Idx) ON (n.v)".into(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();
    while tokio_stream::StreamExt::next(&mut stream).await.is_some() {}

    // Same query after index - should still return correct results
    let after = query_int_column(&mut client, query).await;
    assert_eq!(after, vec![10, 20]);
}

