/// All stream messages in a Vec.
async fn collect_stream(
    stream: &mut tonic::Streaming<proto::ExecuteQueryResponse>,
) -> Vec<proto::ExecuteQueryResponse> {
    let mut msgs = vec![];
    while let Some(msg) = tokio_stream::StreamExt::next(stream).await {
        msgs.push(msg.unwrap());
    }
    msgs
}

/// Footer of a message stream.
fn extract_footer(msgs: &[proto::ExecuteQueryResponse]) -> &proto::QueryFooter {
    msgs.iter()
        .find_map(|m| match &m.payload {
            Some(proto::execute_query_response::Payload::Footer(f)) => Some(f),
            _ => None,
        })
        .expect("expected footer in stream")
}

