#[tokio::test]
async fn begin_transaction_on_named_database() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();

    // Create a second database
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "CREATE DATABASE txdb".into(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();
    collect_stream(&mut stream).await;

    // Begin transaction on the new database
    let tx_resp = client
        .begin_transaction(proto::BeginTransactionRequest {
            database: "txdb".into(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();

    let tx_id = tx_resp.transaction_id;

    // Execute query in the transaction
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "CREATE (n:TxDb {v: 1}) RETURN n.v".into(),
            transaction_id: tx_id.clone(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();

    let msgs = collect_stream(&mut stream).await;
    let footer = extract_footer(&msgs);
    assert_eq!(footer.database, "txdb");

    // Commit
    client
        .commit_transaction(proto::CommitTransactionRequest {
            transaction_id: tx_id,
        })
        .await
        .unwrap();

    // Verify data is in txdb, not in neo4j
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "MATCH (n:TxDb) RETURN n.v".into(),
            database: "txdb".into(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();

    let msgs = collect_stream(&mut stream).await;
    let rows: Vec<_> = msgs
        .iter()
        .filter_map(|m| match &m.payload {
            Some(proto::execute_query_response::Payload::Row(r)) => Some(r),
            _ => None,
        })
        .collect();
    assert_eq!(rows.len(), 1);
}

