// -- Notification tests ----------------------------------------------

/// All notifications of a streaming query response.
async fn collect_notifications(
    stream: &mut tonic::Streaming<proto::ExecuteQueryResponse>,
) -> Vec<proto::Notification> {
    let mut notifications = vec![];
    while let Some(msg) = stream.message().await.unwrap() {
        if let Some(proto::execute_query_response::Payload::Footer(footer)) = msg.payload {
            notifications = footer.notifications;
        }
    }
    notifications
}

#[tokio::test]
async fn notification_cartesian_product() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();

    // Create some nodes so MATCH has something to work with
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "CREATE (:A), (:B)".into(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();
    while stream.message().await.unwrap().is_some() {}

    // Two MATCH clauses -> CartesianProduct warning
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "MATCH (a:A) MATCH (b:B) RETURN a, b".into(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();

    let notifications = collect_notifications(&mut stream).await;
    assert_eq!(notifications.len(), 1);
    assert_eq!(
        notifications[0].code,
        "Neo.ClientNotification.Statement.CartesianProductWarning"
    );
    assert_eq!(notifications[0].severity, "WARNING");
}

