#[tokio::test]
async fn read_only_mode_rejects_write_query() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();

    // Auto-commit write query with access_mode "r" should fail
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "CREATE (n:Forbidden)".into(),
            access_mode: "r".into(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();

    // The error comes through the stream (inside spawn_blocking)
    let msg = tokio_stream::StreamExt::next(&mut stream).await.unwrap();
    assert!(msg.is_err());
    let err = msg.unwrap_err();
    assert_eq!(err.code(), tonic::Code::PermissionDenied);
    assert!(
        err.message().contains("read access mode"),
        "expected 'read access mode' in error, got: {}",
        err.message()
    );
}

