#[tokio::test]
async fn read_only_transaction_rejects_writes() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();

    let tx_id = client
        .begin_transaction(proto::BeginTransactionRequest {
            access_mode: "r".into(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner()
        .transaction_id;

    // the run request's own access mode defaults to "w"; the transaction's mode still wins
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "CREATE (n:Forbidden)".into(),
            transaction_id: tx_id.clone(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();
    let err = tokio_stream::StreamExt::next(&mut stream)
        .await
        .unwrap()
        .unwrap_err();
    assert_eq!(err.code(), tonic::Code::PermissionDenied);

    let err = client
        .create_node(proto::CreateNodeRequest {
            labels: vec!["Forbidden".into()],
            properties: Default::default(),
            transaction_id: tx_id.clone(),
        })
        .await
        .unwrap_err();
    assert_eq!(err.code(), tonic::Code::PermissionDenied);

    // reads still work, and nothing was written
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "MATCH (n:Forbidden) RETURN count(n) AS c".into(),
            transaction_id: tx_id.clone(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();
    while let Some(msg) = tokio_stream::StreamExt::next(&mut stream).await {
        msg.unwrap();
    }
    client
        .commit_transaction(proto::CommitTransactionRequest {
            transaction_id: tx_id,
        })
        .await
        .unwrap();
    let count = client
        .get_node_count(proto::GetNodeCountRequest {})
        .await
        .unwrap()
        .into_inner()
        .count;
    assert_eq!(count, 0);
}

// -- dirty flag --------------------------------------------------------
// gRPC writes must mark the database dirty, or snapshot-mode persist-all (/api/save, graceful
// shutdown, /api/quiesce) skips databases written only over gRPC and their acked writes are lost.

/// Harness variant returning the registry, so tests can inspect the dirty flag.
async fn start_grpc_server_with_registry() -> (
    String,
    tokio::sync::oneshot::Sender<()>,
    Arc<DatabaseRegistry>,
) {
    let store = Arc::new(MvccStore::new(Graph::new()));
    let registry = Arc::new(DatabaseRegistry::single("neo4j".to_string(), store, None));
    let (shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel();
    let grpc = GrpcServer::new(Arc::clone(&registry), "127.0.0.1:0".parse().unwrap());
    let addr = grpc.run_until_shutdown(shutdown_rx).await.unwrap();
    let url = format!("http://{addr}");
    tokio::time::sleep(std::time::Duration::from_millis(50)).await;
    (url, shutdown_tx, registry)
}

fn clear_dirty(registry: &DatabaseRegistry) {
    registry
        .get("neo4j")
        .unwrap()
        .dirty
        .store(false, std::sync::atomic::Ordering::Relaxed);
}

fn is_dirty(registry: &DatabaseRegistry) -> bool {
    registry
        .get("neo4j")
        .unwrap()
        .dirty
        .load(std::sync::atomic::Ordering::Relaxed)
}

#[tokio::test]
async fn create_node_rpc_marks_database_dirty() {
    let (url, _shutdown, registry) = start_grpc_server_with_registry().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();
    clear_dirty(&registry);

    client
        .create_node(proto::CreateNodeRequest {
            labels: vec!["Person".into()],
            properties: [("name".into(), string_val("Alice"))].into_iter().collect(),
            transaction_id: String::new(),
        })
        .await
        .unwrap();

    assert!(
        is_dirty(&registry),
        "create_node must mark the database dirty"
    );
}

#[tokio::test]
async fn cypher_write_query_marks_database_dirty() {
    let (url, _shutdown, registry) = start_grpc_server_with_registry().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();
    clear_dirty(&registry);

    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "CREATE (n:City {name: 'Stockholm'})".into(),
            parameters: Default::default(),
            transaction_id: String::new(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();
    while let Some(msg) = tokio_stream::StreamExt::next(&mut stream).await {
        msg.unwrap();
    }

    assert!(
        is_dirty(&registry),
        "auto-commit write query must mark dirty"
    );

    // Read-only query must NOT re-dirty a clean database
    clear_dirty(&registry);
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "MATCH (n:City) RETURN n.name".into(),
            parameters: Default::default(),
            transaction_id: String::new(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();
    while let Some(msg) = tokio_stream::StreamExt::next(&mut stream).await {
        msg.unwrap();
    }
    assert!(!is_dirty(&registry), "read query must not mark dirty");
}

#[tokio::test]
async fn explicit_transaction_commit_marks_database_dirty() {
    let (url, _shutdown, registry) = start_grpc_server_with_registry().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();
    clear_dirty(&registry);

    let tx = client
        .begin_transaction(proto::BeginTransactionRequest {
            database: String::new(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();

    client
        .create_node(proto::CreateNodeRequest {
            labels: vec!["Person".into()],
            properties: [("name".into(), string_val("Bob"))].into_iter().collect(),
            transaction_id: tx.transaction_id.clone(),
        })
        .await
        .unwrap();

    // Mutation buffered in the session: not dirty until commit
    assert!(!is_dirty(&registry), "uncommitted tx must not mark dirty");

    client
        .commit_transaction(proto::CommitTransactionRequest {
            transaction_id: tx.transaction_id,
        })
        .await
        .unwrap();

    assert!(is_dirty(&registry), "commit_transaction must mark dirty");
}

/// Runs a query inside `tx_id`, draining the stream.
async fn run_in_tx(
    client: &mut TraverseServiceClient<tonic::transport::Channel>,
    tx_id: &str,
    query: &str,
) {
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: query.into(),
            transaction_id: tx_id.to_string(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();
    while let Some(item) = tokio_stream::StreamExt::next(&mut stream).await {
        item.unwrap();
    }
}

#[tokio::test]
async fn concurrent_transactions_on_one_node_abort_the_second() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();
    let mut setup = client.clone();
    let mut s = setup
        .execute_query(proto::ExecuteQueryRequest {
            query: "CREATE (:Counter {n: 0})".into(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();
    while tokio_stream::StreamExt::next(&mut s).await.is_some() {}

    let begin = |c: &mut TraverseServiceClient<tonic::transport::Channel>| {
        let mut c = c.clone();
        async move {
            c.begin_transaction(proto::BeginTransactionRequest::default())
                .await
                .unwrap()
                .into_inner()
                .transaction_id
        }
    };
    let t1 = begin(&mut client).await;
    let t2 = begin(&mut client).await;
    run_in_tx(&mut client, &t1, "MATCH (c:Counter) SET c.n = c.n + 1").await;
    run_in_tx(&mut client, &t2, "MATCH (c:Counter) SET c.n = c.n + 1").await;
    client
        .commit_transaction(proto::CommitTransactionRequest { transaction_id: t1 })
        .await
        .unwrap();
    let err = client
        .commit_transaction(proto::CommitTransactionRequest { transaction_id: t2 })
        .await
        .unwrap_err();
    assert_eq!(err.code(), tonic::Code::Aborted, "{err:?}");

    let n = query_int_column(&mut client, "MATCH (c:Counter) RETURN c.n AS n").await;
    assert_eq!(n, vec![1]);
}

// -- stopping statements: dropped streams, timeouts, TERMINATE TRANSACTIONS --

/// Rows of one query, as plain values (`None` on an error status).
async fn query_rows(
    client: &mut TraverseServiceClient<tonic::transport::Channel>,
    query: &str,
    params: Vec<(&str, proto::Value)>,
    transaction_id: &str,
) -> Result<Vec<Vec<proto::Value>>, tonic::Status> {
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: query.into(),
            parameters: params
                .into_iter()
                .map(|(k, v)| (k.to_string(), v))
                .collect(),
            transaction_id: transaction_id.into(),
            ..Default::default()
        })
        .await?
        .into_inner();
    let mut rows = Vec::new();
    while let Some(msg) = tokio_stream::StreamExt::next(&mut stream).await {
        if let Some(proto::execute_query_response::Payload::Row(r)) = msg?.payload {
            rows.push(r.values);
        }
    }
    Ok(rows)
}

/// A server with 2,000 `:Big` nodes: a three-way cross product over them runs for minutes.
async fn grpc_server_with_big_graph() -> (
    String,
    tokio::sync::oneshot::Sender<()>,
    TraverseServiceClient<tonic::transport::Channel>,
) {
    let (url, shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url.clone()).await.unwrap();
    query_rows(
        &mut client,
        "UNWIND range(1, 2000) AS i CREATE (:Big {i: i})",
        vec![],
        "",
    )
    .await
    .unwrap();
    (url, shutdown, client)
}

/// Statements whose text is `query`, as SHOW TRANSACTIONS lists them.
async fn running_count(
    client: &mut TraverseServiceClient<tonic::transport::Channel>,
    query: &str,
) -> i64 {
    let rows = query_rows(
        client,
        "SHOW TRANSACTIONS YIELD currentQuery WHERE currentQuery = $q RETURN count(*)",
        vec![("q", string_val(query))],
        "",
    )
    .await
    .unwrap();
    match rows[0][0].kind {
        Some(Kind::IntValue(n)) => n,
        ref other => panic!("{other:?}"),
    }
}

/// Waits (up to 20 s) until `done` holds.
async fn eventually<F, Fut>(mut done: F, what: &str)
where
    F: FnMut() -> Fut,
    Fut: std::future::Future<Output = bool>,
{
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
    while !done().await {
        assert!(std::time::Instant::now() < deadline, "{what}");
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn dropping_the_response_stream_stops_the_statement() {
    let (url, _shutdown, mut observer) = grpc_server_with_big_graph().await;
    let query = "MATCH (a:Big), (b:Big), (c:Big) RETURN count(*) AS dropped";
    let mut client = TraverseServiceClient::connect(url).await.unwrap();
    let stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: query.into(),
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();
    eventually(
        || {
            let mut o = observer.clone();
            async move { running_count(&mut o, query).await == 1 }
        },
        "the statement never started",
    )
    .await;
    drop(stream);
    eventually(
        || {
            let mut o = observer.clone();
            async move { running_count(&mut o, query).await == 0 }
        },
        "the statement kept running after its client went away",
    )
    .await;
    let _ = running_count(&mut observer, query).await;
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_request_timeout_stops_the_statement() {
    let (_url, _shutdown, mut client) = grpc_server_with_big_graph().await;
    let started = std::time::Instant::now();
    let mut stream = client
        .execute_query(proto::ExecuteQueryRequest {
            query: "MATCH (a:Big), (b:Big), (c:Big) RETURN count(*) AS timed".into(),
            timeout_ms: 300,
            ..Default::default()
        })
        .await
        .unwrap()
        .into_inner();
    let mut status = None;
    while let Some(msg) = tokio_stream::StreamExt::next(&mut stream).await {
        if let Err(e) = msg {
            status = Some(e);
            break;
        }
    }
    let status = status.expect("the statement must fail");
    assert_eq!(status.code(), tonic::Code::DeadlineExceeded, "{status:?}");
    assert!(started.elapsed() < std::time::Duration::from_secs(20));
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_terminated_transaction_cannot_commit() {
    let (_url, _shutdown, mut client) = grpc_server_with_big_graph().await;
    let tx_id = client
        .begin_transaction(proto::BeginTransactionRequest::default())
        .await
        .unwrap()
        .into_inner()
        .transaction_id;
    query_rows(&mut client, "CREATE (:FromGrpcTx)", vec![], &tx_id)
        .await
        .unwrap();
    // it's listed as a grpc transaction; terminate it
    let rows = query_rows(
        &mut client,
        "SHOW TRANSACTIONS YIELD transactionId, protocol, connectionId \
         WHERE protocol = 'grpc' AND currentQuery = '' RETURN transactionId",
        vec![],
        "",
    )
    .await
    .unwrap();
    assert!(!rows.is_empty(), "the open transaction is listed");
    for row in rows {
        query_rows(
            &mut client,
            "TERMINATE TRANSACTIONS $id",
            vec![("id", row[0].clone())],
            "",
        )
        .await
        .unwrap();
    }
    let err = client
        .commit_transaction(proto::CommitTransactionRequest {
            transaction_id: tx_id,
        })
        .await
        .unwrap_err();
    assert_eq!(err.code(), tonic::Code::Aborted, "{err:?}");
    let count = query_rows(
        &mut client,
        "MATCH (n:FromGrpcTx) RETURN count(n)",
        vec![],
        "",
    )
    .await
    .unwrap();
    assert_eq!(count[0][0].kind, Some(Kind::IntValue(0)));
}

#[tokio::test]
async fn a_statement_that_fails_after_writing_fails_its_transaction() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();
    let tx_id = client
        .begin_transaction(proto::BeginTransactionRequest::default())
        .await
        .unwrap()
        .into_inner()
        .transaction_id;
    // a syntax error changes nothing: the transaction carries on
    assert!(
        query_rows(&mut client, "CREATE (:Kept", vec![], &tx_id)
            .await
            .is_err()
    );
    query_rows(&mut client, "CREATE (:Kept)", vec![], &tx_id)
        .await
        .unwrap();
    // this one creates a node, then fails
    assert!(
        query_rows(
            &mut client,
            "CREATE (:Partial) WITH 1 AS one RETURN 10 / 0",
            vec![],
            &tx_id
        )
        .await
        .is_err()
    );
    let err = query_rows(&mut client, "RETURN 1", vec![], &tx_id)
        .await
        .unwrap_err();
    assert_eq!(err.code(), tonic::Code::FailedPrecondition, "{err:?}");
    let err = client
        .commit_transaction(proto::CommitTransactionRequest {
            transaction_id: tx_id.clone(),
        })
        .await
        .unwrap_err();
    assert_eq!(err.code(), tonic::Code::FailedPrecondition, "{err:?}");
    // the refused commit rolled it back: nothing is left to roll back
    let err = client
        .rollback_transaction(proto::RollbackTransactionRequest {
            transaction_id: tx_id,
        })
        .await
        .unwrap_err();
    assert_eq!(err.code(), tonic::Code::NotFound, "{err:?}");
    let count = query_rows(&mut client, "MATCH (n) RETURN count(n)", vec![], "")
        .await
        .unwrap();
    assert_eq!(count[0][0].kind, Some(Kind::IntValue(0)));
}

#[tokio::test]
async fn errors_carry_their_gql_status() {
    let (url, _shutdown) = start_grpc_server().await;
    let mut client = TraverseServiceClient::connect(url).await.unwrap();
    for (query, code, gql) in [
        ("RETURN 1 / 0", tonic::Code::InvalidArgument, "22012"),
        ("RETURN x", tonic::Code::InvalidArgument, "42N62"),
        ("CALL no.such.procedure()", tonic::Code::NotFound, "42N08"),
    ] {
        let err = query_rows(&mut client, query, vec![], "")
            .await
            .unwrap_err();
        assert_eq!(err.code(), code, "{query}: {err:?}");
        assert_eq!(
            err.metadata()
                .get("gql-status")
                .and_then(|v| v.to_str().ok()),
            Some(gql),
            "{query}: {err:?}"
        );
    }
}
